 namespace Pterodactyl\Services\Dezerx\Drive; use Throwable; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Log; use Pterodactyl\Services\Dezerx\Addons; class GoogleDrive { private const OAUTH = 'https://oauth2.googleapis.com/token'; private const AUTH = 'https://accounts.google.com/o/oauth2/v2/auth'; private const API = 'https://www.googleapis.com/drive/v3'; private const UPLOAD = 'https://www.googleapis.com/upload/drive/v3/files'; public const SCOPE = 'https://www.googleapis.com/auth/drive.file'; private const STALL_BYTES = 1024; private const STALL_SECONDS = 180; private ?string $lastError = null; public function __construct(private ?string $accessToken = null) { } public function lastError(): ?string { return $this->lastError; } public static function clientId(): string { return (string) (Addons::get(Addons::DRIVE_BACKUPS)['google_client_id'] ?? ''); } public static function clientSecret(): string { return (string) (Addons::get(Addons::DRIVE_BACKUPS)['google_client_secret'] ?? ''); } public static function configured(): bool { return self::clientId() !== '' && self::clientSecret() !== ''; } public static function consentUrl(string $redirect, string $state): string { return self::AUTH . '?' . http_build_query([ 'client_id' => self::clientId(), 'redirect_uri' => $redirect, 'response_type' => 'code', 'scope' => self::SCOPE, 'access_type' => 'offline', 'prompt' => 'consent', 'include_granted_scopes' => 'true', 'state' => $state, ]); } public static function exchange(string $code, string $redirect): ?array { $response = Http::asForm()->timeout(20)->post(self::OAUTH, [ 'code' => $code, 'client_id' => self::clientId(), 'client_secret' => self::clientSecret(), 'redirect_uri' => $redirect, 'grant_type' => 'authorization_code', ]); if ($response->failed() || !is_string($response->json('refresh_token'))) { Log::warning('Google Drive: token exchange failed', [ 'status' => $response->status(), 'body' => mb_substr($response->body(), 0, 300), ]); return null; } return [ 'refresh_token' => (string) $response->json('refresh_token'), 'access_token' => (string) $response->json('access_token'), ]; } public static function forRefreshToken(string $refreshToken): ?self { $response = Http::asForm()->timeout(20)->post(self::OAUTH, [ 'refresh_token' => $refreshToken, 'client_id' => self::clientId(), 'client_secret' => self::clientSecret(), 'grant_type' => 'refresh_token', ]); if ($response->failed() || !is_string($response->json('access_token'))) { Log::warning('Google Drive: refresh failed', [ 'status' => $response->status(), 'body' => mb_substr($response->body(), 0, 300), ]); return null; } return new self((string) $response->json('access_token')); } public function account(): ?string { $response = $this->http()->get('https://www.googleapis.com/oauth2/v2/userinfo'); return $response->successful() ? $response->json('email') : null; } public function folder(string $name, ?string $known = null): ?string { if ($known !== null && $known !== '') { $existing = $this->http()->get(self::API . "/files/{$known}", ['fields' => 'id,trashed']); if ($existing->successful() && $existing->json('trashed') !== true) { return $known; } } $created = $this->http()->post(self::API . '/files', [ 'name' => $name, 'mimeType' => 'application/vnd.google-apps.folder', ]); if ($created->failed()) { $this->lastError = self::reason($created->status(), $created->body()); Log::warning('Google Drive: the folder could not be opened', [ 'status' => $created->status(), 'body' => mb_substr($created->body(), 0, 300), ]); return null; } return $created->json('id'); } public static function reason(int $status, string $body): string { $decoded = json_decode($body, true); /* 438d11c97b7aa73523f04169c265d334 */ $message = is_array($decoded) ? (string) ($decoded['error']['message'] ?? '') : ''; if (str_contains($message, 'has not been used in project') || str_contains($message, 'accessNotConfigured')) { return 'the Google Drive API is not switched on for this panel\'s Google Cloud project. An administrator enables it in the Google Cloud console, then it works without reconnecting.'; } if ($status === 401) { return 'Google refused the connection. Reconnect the account.'; } if ($status === 403 && str_contains($message, 'insufficient')) { return 'this panel\'s Google connection was not granted permission to write files. Reconnect the account.'; } if ($status === 403 && (str_contains($message, 'quota') || str_contains($message, 'storage'))) { return 'the Drive is out of space, or the account is over its quota.'; } return $message !== '' ? 'Google answered ' . $status . ': ' . mb_substr($message, 0, 160) : 'Google answered ' . $status . '.'; } public function upload(string $source, string $folderId, string $name, ?int $size = null): ?string { $start = $this->http() ->withHeaders(['X-Upload-Content-Type' => 'application/gzip']) ->post(self::UPLOAD . '?uploadType=resumable', [ 'name' => $name, 'parents' => [$folderId], ]); $session = $start->header('Location'); if ($start->failed() || $session === '') { $this->lastError = self::reason($start->status(), $start->body()); Log::warning('Google Drive: could not open an upload session', [ 'status' => $start->status(), 'body' => mb_substr($start->body(), 0, 300), ]); return null; } $handle = @fopen($source, 'rb'); if ($handle === false) { $this->lastError = 'the backup could not be read from the node.'; Log::warning('Google Drive: the backup could not be opened for upload'); return null; } $length = self::sourceLength($handle) ?? ($size !== null && $size > 0 ? $size : null); try { $response = Http::withBody($handle, 'application/gzip') ->withOptions([ 'timeout' => 0, 'curl' => [ CURLOPT_LOW_SPEED_LIMIT => self::STALL_BYTES, CURLOPT_LOW_SPEED_TIME => self::STALL_SECONDS, ], ]) ->withHeaders(array_filter([ 'Content-Length' => $length !== null ? (string) $length : null, ])) ->put($session); if ($response->failed()) { $this->lastError = self::reason($response->status(), $response->body()); Log::warning('Google Drive: upload rejected', [ 'status' => $response->status(), 'body' => mb_substr($response->body(), 0, 300), ]); return null; } return $response->json('id'); } catch (Throwable $exception) { $this->lastError = 'the transfer stopped: ' . mb_substr($exception->getMessage(), 0, 160); Log::warning('Google Drive: upload failed', ['error' => $exception->getMessage()]); return null; } finally { @fclose($handle); } } private static function sourceLength(mixed $handle): ?int { foreach ((array) (stream_get_meta_data($handle)['wrapper_data'] ?? []) as $header) { if (preg_match('/^content-length:\s*(\d+)/i', (string) $header, $match) === 1) { return (int) $match[1]; } } return null; } public function contents(string $folderId): array { $response = $this->http()->get(self::API . '/files', [ 'q' => "'{$folderId}' in parents and trashed = false", 'fields' => 'files(id,name,size,createdTime)', 'orderBy' => 'createdTime desc', 'pageSize' => 100, ]); if ($response->failed()) { return []; } return array_map(fn (array $file) => [ 'id' => (string) ($file['id'] ?? ''), 'name' => (string) ($file['name'] ?? ''), 'size' => (int) ($file['size'] ?? 0), 'createdTime' => $file['createdTime'] ?? null, ], $response->json('files') ?? []); } public function delete(string $fileId): bool { return $this->http()->delete(self::API . "/files/{$fileId}")->successful(); } private function http() { return Http::withToken((string) $this->accessToken)->timeout(30); } } 